// The monorepo inventory, generated by scripts/inventory.ts and served by /api/packages.
import data from "./generated/inventory.json";

export interface PackageInfo {
  name: string;
  version: string;
  description: string;
  dir: string;
  kind: "package" | "app";
  workspace: boolean;
  private: boolean;
  exports: number;
  bin: string[];
}

export const PACKAGES: readonly PackageInfo[] = data as PackageInfo[];

/** Packages by name. */
export const byName = (name: string): PackageInfo | undefined => PACKAGES.find(p => p.name === name);
